import { expect, test } from '../fixtures';

// Starts from the user session, not the default one.
test.use({ storageState: process.env.SOVA_AUTH_STATE_USER! });

test('Settings wrong current password', async ({ page }) => {
  await test.step('Open the settings', async () => {
    await page.goto('/settings');
  });

  await test.step('Type a wrong current password', async () => {
    await page.getByRole('textbox', { name: 'Current Password', exact: true }).fill('not-my-password');
  });

  await test.step('Type a new password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('another-pass-456');
  });

  await test.step('Press Submit', async () => {
    await page.getByRole('button', { name: 'Submit', exact: true }).click();
  });

  await test.step('The wrong-password error is shown', async () => {
    await expect(page.locator('text=Your previous password is incorrect')).toBeVisible();
  });
});
